import time

class Thermostat:
    VALID_MODES = ['heat', 'cool']

    def __init__(self, current_temperature, target_temperature, mode):
        self._current_temperature = current_temperature
        self._target_temperature = target_temperature
        self._mode = mode if mode in Thermostat.VALID_MODES else None

    @property
    def current_temperature(self):
        return self._current_temperature

    @property
    def target_temperature(self):
        return self._target_temperature

    @target_temperature.setter
    def target_temperature(self, temperature):
        self._target_temperature = temperature

    @property
    def mode(self):
        return self._mode

    @mode.setter
    def mode(self, mode):
        if mode in Thermostat.VALID_MODES:
            self._mode = mode
        else:
            # Keep existing behavior of returning False for invalid mode,
            # but typically setters don't return values. 
            # Since original method returned boolean, we'll adjust signature or usage.
            # For strict encapsulation, we might raise an exception, but sticking to original logic:
            pass

    def set_mode(self, mode):
        if mode in Thermostat.VALID_MODES:
            self._mode = mode
            return True
        else:
            return False

    def auto_set_mode(self):
        if self.current_temperature < self.target_temperature:
            self._mode = 'heat'
        else:
            self._mode = 'cool'

    def auto_check_conflict(self):
        if self.current_temperature > self.target_temperature:
            return self._mode == 'cool' or (self.auto_set_mode(), False)[1]
        else:
            return self._mode == 'heat' or (self.auto_set_mode(), False)[1]

    def simulate_operation(self):
        self.auto_set_mode()
        return self._calculate_time_to_target()

    def _calculate_time_to_target(self):
        if self.mode == 'heat':
            return self._heat_time()
        else:
            return self._cool_time()

    def _heat_time(self):
        use_time = 0
        while self._current_temperature < self._target_temperature:
            self._current_temperature += 1
            use_time += 1
        return use_time

    def _cool_time(self):
        use_time = 0
        while self._current_temperature > self._target_temperature:
            self._current_temperature -= 1
            use_time += 1
        return use_time

